<?php
declare(strict_types=1);
require __DIR__ . '/../config/config.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$medicineId=(int)($_POST['medicine_id']??0);$boxes=max(0,(int)($_POST['boxes']??0));$strips=max(0,(int)($_POST['strips']??0));$units=max(0,(int)($_POST['units']??0));$batch=trim($_POST['batch_no']??'');$m=db()->prepare('SELECT * FROM medicines WHERE id=?');$m->execute([$medicineId]);$medicine=$m->fetch();if(!$medicine)exit('Medicine not found.');$total=$boxes*(int)$medicine['strips_per_box']*(int)$medicine['units_per_strip']+$strips*(int)$medicine['units_per_strip']+$units;if($total<1)exit('Enter at least one box, strip, or tablet.');$s=db()->prepare('INSERT INTO batches(medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES(?,?,?,?,?,?)');$s->execute([$medicineId,$batch!==''?$batch:null,$_POST['expiry_date']?:null,$total,$total,max(0,(float)($_POST['purchase_unit_cost']??0))]);$bid=(int)db()->lastInsertId();db()->prepare('INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,note) VALUES(?,?,"purchase",?,?)')->execute([$medicineId,$bid,$total,'Stock received']);header('Location: inventory-modern.php?saved=1');exit;}
$meds=db()->query('SELECT id,name,units_per_strip,strips_per_box FROM medicines WHERE active=1 ORDER BY name')->fetchAll();$rows=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id GROUP BY m.id ORDER BY m.name')->fetchAll();function ei(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory · <?=ei(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.note{background:#eef5ff;border:1px solid #cfe0ff;border-radius:10px;padding:12px;color:#34527e;margin-bottom:16px}.grid label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:700;color:#536078}</style></head><body><header><div class="brand">💊 <?=ei(APP_NAME)?></div><nav><a href="index.php?action=dashboard">Dashboard</a><a href="pos-modern.php">POS</a><a href="index.php?action=medicines">Medicines</a><a class="active" href="inventory-modern.php">Inventory</a><a href="index.php?action=reports">Reports</a></nav></header><main><div class="page-title"><div><div class="eyebrow">STOCK CONTROL</div><h1>Inventory</h1><p>Receive stock in boxes, strips or individual units.</p></div></div><div class="panel"><div class="note"><b>Batch number is optional.</b> Leave it blank when your supplier does not provide a batch number. Expiry date is also optional.</div><h2>Receive Stock</h2><form method="post" class="grid"><label>Medicine *<select name="medicine_id" required><option value="">Select medicine</option><?php foreach($meds as $m):?><option value="<?=$m['id']?>"><?=ei($m['name'])?> · <?=$m['units_per_strip']?>/strip · <?=$m['strips_per_box']?> strips/box</option><?php endforeach;?></select></label><label>Batch Number <span style="font-weight:400">(optional)</span><input name="batch_no" placeholder="Leave blank if unavailable"></label><label>Expiry Date <span style="font-weight:400">(optional)</span><input type="date" name="expiry_date"></label><label>Boxes<input type="number" name="boxes" min="0" value="0"></label><label>Strips<input type="number" name="strips" min="0" value="0"></label><label>Tablets / Units<input type="number" name="units" min="0" value="0"></label><label>Cost / smallest unit<input type="number" step="0.0001" name="purchase_unit_cost" min="0" value="0"></label><button class="btn">Receive Stock</button></form></div><div class="panel"><h2>Current Stock</h2><table><tr><th>Medicine</th><th>Stock</th><th>Reorder Level</th></tr><?php foreach($rows as $r):?><tr><td><b><?=ei($r['name'])?></b><small><?=ei($r['generic_name'])?> <?=ei($r['strength'])?></small></td><td><b><?=$r['stock']?></b> units</td><td><?=$r['reorder_level']?></td></tr><?php endforeach;?></table></div></main></body></html>
